// v16.xx (coop12), HIS ORDER (2026-10-14), the two player first: PLAYER 2 HEARS THE WAVE CALL. The pack the Director sends lands as bodies, which come over to player 2 with the rest, but the call that
// goes with it (WAVE 5, and AMBUSH when it comes from behind, with the announcer cue) was said in the host window only, so player 2 met a pack with no word. The host now says how many waves it has
// sent and how many of them were ambushes in the same world word; the linked window says the call when the count goes up (never for the count it first hears, so joining late is quiet).
function waveNetOut(){
  var WS=G.arcade?ARCADE:G.cs, D=G.flow&&G.flow.dir;
  if(!WS) return 0;
  return [WS.waveN|0,(D&&D.amb)|0];
}
function waveNetTake(a){
  var S=flowS(), n, am;
  if(!a||typeof a.length!=='number'||a.length<2) return 0;
  n=a[0]|0; am=a[1]|0;
  if(typeof S.wnP==='number'&&n>S.wnP){
    try{ say('WAVE '+n,'warn',(am>(S.wnA|0))?{sub:'AMBUSH'}:undefined); }catch(_w){}
    try{ annCue('WAVE'); }catch(_vc){}
  }
  S.wnP=n; S.wnA=am;
  return n;
}
// FLOW-MODULE-END (the next flow builds add their code above this line)

