   var bad=[], g=null, p=null, NK={}, k, oSF=netSendFast, oS=netSend, sent=[], w=null, oIv, oSh, oAr, h={seat:0,state:'in'}, hp={seat:1,state:'in'}, staged=false, lines=[], rs=say, own=false, D;
   function word(){ var q, r=null; for(q=sent.length-1;q>=0;q--) if(sent[q].t==='wd'){ r=sent[q]; break; } return r; }
   function sendTake(){ sent.length=0; NET.role='host'; NET.seat=0; NET.peers=[hp]; netWorldSend(); w=word(); NET.role='join'; NET.seat=1; NET.peers=[h]; if(w) netOnMsg(h,JSON.stringify(w)); return w; }
   try{
     __topClear(); __runPrep();
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; keys={}; oSh=p.arcSh; oAr=p.armor; oIv=p.iv; p.arcSh=0; p.armor=0; p.iv=99;
     say=function(m,kd,o){ lines.push(String(m)+'|'+((o&&o.sub)||'')); }; own=true;
     for(k in NET) NK[k]=NET[k];
