     g.flow=g.flow||{}; D=g.flow.dir=g.flow.dir||{st:0,hp:100,quiet:0,ph:'build',phT:0,waves:0,amb:0,lastAmb:-999,pace:1};
     // ONE: the first word only teaches the count: nothing is said for a raid already on wave 3
     ARCADE.waveN=3; D.amb=1;
