     ARCADE.waveN=4; D.amb=2; lines.length=0; sendTake();
     if(!lines.some(function(m){ return /^WAVE 4\|AMBUSH/.test(m); })) bad.push('TWO: player 2 was not told WAVE 4 with AMBUSH ('+lines.join(' / ')+')');
     // THREE: wave 5, not an ambush: WAVE 5 alone; and the same word again says nothing
     ARCADE.waveN=5; lines.length=0; sendTake();
     if(!lines.some(function(m){ return /^WAVE 5\|$/.test(m); })) bad.push('THREE: player 2 was not told WAVE 5 plain ('+lines.join(' / ')+')');
     lines.length=0; sendTake();
     if(lines.some(function(m){ return /^WAVE/.test(m); })) bad.push('THREE: the same count again was said again ('+lines.join(' / ')+')');
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{
     if(own) say=rs;
     netSendFast=oSF; netSend=oS;
     if(staged){ for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }
